VALUES
('1487220000000', 'F', '0', NULL, 'admin', '2026-02-12 00:00:00', 'admin', '2026-02-12 00:00:00', NULL, '1', '1', NULL, NULL, NULL, 'Axi_metadata_struct_obj', NULL, 'Internal', '1', 'SELECT * from fn_axi_struct_metadata( :pstructtype, :ptransid , :pobjtype )', 'pstructtype,ptransid,pobjtype', 'pstructtype~Character~,ptransid~Character~,pobjtype~Character~', 'ALL', NULL, 'objtype,objcaption,objname,dcname,asgrid', 'F', '6 Hr', NULL, NULL, NULL, NULL, NULL),
