('1181770000000', 'F', '0', NULL, 'vaidheesh', '2026-06-02 20:27:54', 'ashokk', '2026-06-02 14:35:05', NULL, '1', '1', NULL, NULL, NULL, 'Purchase Data', NULL, 'For users', '3', 'select a.docdate,a.docid, s.party_name,a.currency,s.statejurisdiction state,  i.itemdesc,b.uom,b.qty po_qty,b.rate , b.grossamount,b.discamount,b.taxableamount,
b.netamount po_value,grn.grn_qty,round(((grn.grn_qty*b.netamount )/b.qty),2) grn_value,grn.bill_qty,grn.bill_value,grn.returnqty,grn.returned_value,
ic.categoryname,isb.productcategory,br.brand_name,to_char(a.docdate,''Mon'') mnth,to_char(a.docdate,''YYYY'') yr,
concat(''Q'',EXTRACT(QUARTER FROM  a.docdate)) qtr
from po_header a
join po_items b on a.po_headerid  = b.po_headerid 
join item i on b.itemname  = i.itemid 
join itemcategory ic on i.itemcategory  = ic.itemcategoryid
join productcategory isb on i.productcategory  = isb.productcategoryid 
join brand_master br on i.itembrand  = br.brand_masterid 
join mg_supplier s on a.supplier  = s.mg_supplierid 
left outer join (select b.po_itemsid,sum(b.qty ) grn_qty,sum(pb.bill_qty) bill_qty,sum(pb.net_amount) bill_value,
sum(pr.returnqty) returnqty,sum(pr.returned_value) returned_value
from grn_header a join grn_items b on a.grn_headerid  = b.grn_headerid 
left outer join (select b.grn_itemsid,sum(b.qty ) bill_qty,sum(b.netamount) net_amount from 
purchase_bill_header a
join Purchase_bill_items b on a.purchase_bill_headerid  = b.purchase_bill_headerid 
where a.cancel  = ''F'' and a.company  = cast( :m_companyid as numeric) group by grn_itemsid ) pb on b.grn_itemsid = pb.grn_itemsid
left outer join (select b.grn_itemsid ,sum(b.returnqty) returnqty, sum(b.netamount) returned_value
from purchasereturn_header a
join purchasereturn_items b on a.purchasereturn_headerid  = b.purchasereturn_headerid 
where a.cancel  = ''F''  and a.company  = cast( :m_companyid as numeric)
group by b.grn_itemsid ) pr on b.grn_itemsid = pb.grn_itemsid
where a.cancel  = ''F'' and a.company  = cast( :m_companyid as numeric) group by b.po_itemsid  ) grn on  b.po_itemsid = grn.po_itemsid
where a.cancel  = ''F''
and a.company  = cast( :m_companyid as numeric)
order by a.docdate', 'm_companyid', 'm_companyid~Numeric~', 'ALL', NULL, 'docdate,docid,party_name,currency,state,itemdesc,uom,po_qty,rate,grossamount,discamount,taxableamount,po_value,grn_qty,grn_value,bill_qty,bill_value,returnqty,returned_value,categoryname,productcategory,brand_name,mnth,yr,qtr', 'F', '1 Hr', NULL, 'Purchase Data', NULL, 'T', 'F'),
('1182440000000', 'F', '0', NULL, 'ashokk', '2026-06-02 14:58:06', 'ashokk', '2026-06-02 14:55:19', NULL, '1', '1', NULL, NULL, NULL, 'Price List Data', NULL, 'For users', '3', 'SELECT
    categoryname,
    subcategory,
    brand_name,
    itemdesc,
    sellingunit,
    primarysellingrate,
    effective_from,
    applicability
FROM (
    SELECT
        b.categoryname,
        c.brand_name,
        d.productcategory AS subcategory,
        a.itemdesc,
        a.sellingunit,
        CASE
            WHEN s.by_customer = ''T'' AND s.by_branch = ''T''
                THEN ''Customers - '' || s.selected_customers || '' | Branches - '' || s.selected_branches
            WHEN s.by_customer = ''T'' and s.by_branch = ''F''
                THEN ''Customers - '' || s.selected_customers
            WHEN s.by_branch = ''T'' and s.by_customer = ''F'' 
                THEN ''Branches - '' || s.selected_branches
            ELSE ''All Customers & All Branches''
        END AS applicability,
        s.fromdt AS effective_from,
        a.itemcode AS itemcode,
        s.primarysellingrate,
        s.sellingpriceid,
        ROW_NUMBER() OVER (
            PARTITION BY
                a.itemdesc,
                COALESCE(s.selected_branches,  ''''),
                COALESCE(s.selected_customers, '''')
            ORDER BY s.fromdt DESC
        ) AS rn
    FROM item a
    JOIN itemcategory b    ON a.itemcategory = b.itemcategoryid
    JOIN brand_master c    ON a.itembrand    = c.brand_masterid
    JOIN productcategory d ON a.productcategory = d.productcategoryid
    JOIN sellingprice s    ON a.itemid = s.itemname
    WHERE a.active  = ''T''
      AND s.active  = ''T''
      AND s.app_desc = 1
     AND a.company = CAST( :m_companyid AS NUMERIC)
) ranked
WHERE rn = 1
ORDER BY
    categoryname,
    brand_name,
    subcategory,
    itemdesc', 'm_companyid', 'm_companyid~Numeric~', 'ALL', NULL, 'categoryname,subcategory,brand_name,itemdesc,sellingunit,primarysellingrate,effective_from,applicability', 'T', '1 Hr', NULL, 'Price List Data', NULL, 'T', 'F'),
('99999999990001', 'F', '0', NULL, 'admin', '2025-12-23 13:22:07', 'admin', '2025-12-19 16:06:57', NULL, '1', '1', NULL, NULL, NULL, 'axi_jobnameslist', NULL, 'Internal', '1', 'select jname as displaydata from axpdef_jobs', NULL, NULL, 'ALL', NULL, NULL, 'F', '6 Hr', NULL, NULL, NULL, NULL, NULL),
