('1188880000000', 'F', '0', NULL, 'ashokk', '2026-06-02 15:49:26', 'ashokk', '2026-06-02 15:49:26', NULL, '1', '1', NULL, NULL, NULL, 'Stock Statement Data', NULL, 'For users', '3', 'select a.branchname,a.locationname,  i.itemdesc, sum(a.opening_qty) opening_qty,sum(a.received_qty) received_qty,sum(a.issued_qty) issued_qty,
sum( a.opening_qty + a.received_qty + a.issued_qty )  as closing_qty,
sum( a.opening_value + a.received_value + a.issued_value )  as closing_value
from
( select a.itemid itemname, a.locationname, a.branchname, a.company, 
sum(received_qty + issued_qty) as opening_qty,sum(a.received_value + issued_value) AS opening_value, 0 issued_qty, 0 AS issued_value,  0 as received_qty, 0 AS received_value
from mv_stockdetails a
where a.cancel = ''F'' and a.company = cast( :pcompanyid as numeric)
and a.docdate < cast( :pfromdate as date) 
group by a.itemid, a.locationname, a.branchname, a.company
union all
select a.itemid itemname, a.locationname, a.branchname, a.company, 0 as opening_qty, 0 AS opening_value, 
case when lower(a.plusorminus) = ''m'' then sum(a.issued_qty)  else 0 end as issued_qty,
case when lower(a.plusorminus) = ''m'' then sum(a.issued_value)  else 0 end as issued_value,
case when lower(a.plusorminus) = ''p'' then sum(a.received_qty)  else 0 end as received_qty_,
case when lower(a.plusorminus) = ''p'' then sum(a.received_value)  else 0 end as received_value
from mv_stockdetails a
where a.cancel = ''F'' and a.company = cast( :pcompanyid as numeric)
and a.docdate between cast( :pfromdate as date)  and  cast( :ptodate as date)
