('1471440000000', 'F', '0', NULL, 'admin', '2026-06-03 18:32:20', 'admin', '2026-01-30 00:00:00', NULL, '1', '1', NULL, NULL, NULL, 'ds_smartlist_ads_metadata', NULL, 'Internal', '1', 'select distinct a.sqlname,b.fldname,b.fldcaption,b.fdatatype, b."normalized" ,
f.tablename sourcetable ,b.srcfldname sourcefld ,hyp_structtype,hl.hyp_transid, REGEXP_REPLACE(hl.tbl_hyperlink, ''^.*?\((.*?)\)'', ''\1'')::text tbl_hyperlink,hl.hyp_inline,
case when smartlistcnd like ''%Dynamic select columns%'' then ''T'' else ''F'' end dynamiccolumns,
 coalesce(b.filter,''No'') filters,
case when smartlistcnd like ''%Pagination%'' then ''T'' else ''F'' end pagination,
case when smartlistcnd like ''%Sorting%'' then ''T'' else ''F'' end sorting,b.srctransid ,b.srcfldname srcfld ,b.srcfldname,
b.axpdef_smartlist_mdatarow,b.hide hide
from axdirectsql a 
left join axpdef_smartlist c on a.sqlname = c.adsname
left join axpdef_smartlist_mdata b on b.axpdef_smartlistid =c.axpdef_smartlistid
left join axpflds f on b.srctransid = f.tstruct and b.srcfldname = f.fname
left join(select axpdef_smartlistid,hfldname,hyp_structtype,hyp_transid, tbl_hyperlink,hyp_inline from axpdef_smartlist_hlink)hl 
on hl.axpdef_smartlistid=c.axpdef_smartlistid and b.fldname = hl.hfldname
where sqlname = :adsname
order by b.axpdef_smartlist_mdatarow', 'adsname', 'adsname~Character~', 'ALL', NULL, 'sqlname,fldname,fldcaption,normalized,sourcetable,sourcefld,hyp_structtype,hyp_transid,tbl_hyperlink,hyp_inline,dynamiccolumns,filters,pagination,sorting', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('1329110000000', 'F', '0', NULL, 'admin', '2026-06-12 16:22:06', 'admin', '2026-06-12 16:22:06', NULL, '1', '1', NULL, NULL, NULL, 'Sales Person wise Profitability Data', NULL, 'For users', '3', 'select sales_person,a.itemdesc,a.itemcode,a.categoryname,a.productcategory,a.brand_name,sum(sell_value) sell_value,round(sum(cost_value),2) cost_value,
round(sum(sell_value) -sum(cost_value),2) profit,round(((sum(sell_value) -sum(cost_value))/sum(sell_value))*100,2) profit_margin,
round(sum(cost_value) /sum(sell_value),2) costtosale_ratio,concat(to_char(a.docdate,''Mon''),''-'',to_char(a.docdate,''YY'')) mnth,to_char(a.docdate,''YYYY'') yr,
concat(''Q'',EXTRACT(QUARTER FROM  a.docdate),''-'',to_char(a.docdate,''YY'')) qtr
from (
select a1.docdate,a1.sales_person, i.itemdesc,i.itemcode,ic.categoryname,isb.productcategory,br.brand_name,a2.net_amount-coalesce (sr.net_amount,0) sell_value,
(case when coalesce(abs(st.calculated_stockvalue),0) = 0 then coalesce(abs(st.amount),0) else coalesce(abs(st.calculated_stockvalue),0) end/st.qty)*
a2.invoice_qty-coalesce (sr.salesreturn_qty,0) cost_value
from 
invoiceheader a1 
join invoiceitems a2 on a1.invoiceheaderid  = a2.invoiceheaderid 
join item i on a2.itemname  = i.itemid 
join itemcategory ic on i.itemcategory  = ic.itemcategoryid
join productcategory isb on i.productcategory  = isb.productcategoryid 
join brand_master br on i.itembrand  = br.brand_masterid 
join stockvalue st on (a2.deliverynote = st.docid and a2.itemname  = st.itemname )
left outer join (select b.salesinvoice_itemsid,sum(salesreturn_qty) salesreturn_qty,sum(net_amount) net_amount from 
salesreturns_header a
join salesreturns_items b on a.salesreturns_headerid  = b.salesreturns_headerid 
where a.cancel  = ''F''  group by salesinvoice_itemsid) sr on a2.invoiceitemsid  = sr.salesinvoice_itemsid
where a1.cancel  = ''F'') a
group by sales_person,a.itemdesc,a.itemcode,a.categoryname,a.productcategory,a.brand_name,concat(to_char(a.docdate,''Mon''),''-'',to_char(a.docdate,''YY'')) ,to_char(a.docdate,''YYYY'') ,
concat(''Q'',EXTRACT(QUARTER FROM  a.docdate),''-'',to_char(a.docdate,''YY''))
order by 1,2', NULL, NULL, 'ALL', NULL, 'sales_person,itemdesc,itemcode,categoryname,productcategory,brand_name,sell_value,cost_value,profit,profit_margin,costtosale_ratio,mnth,yr,qtr', 'T', '1 Hr', NULL, 'Sales Person wise Profitability Data', NULL, 'T', 'F'),
