a.grplevel,
case when a.grplevel = 0 then '''' else a.acategory end as acategory,
coalesce (b.OP,0) as opbal,
coalesce (b.TRADB,0) as debit,
coalesce (b.TRACR,0) as credit,
coalesce (b.CL,0) as clbal, a.applicablebranches, 
a.accountname as accountnameparam, 
concat(a.groupname,'' ('', a.groupcode,'')'') as groupnamewithcode,
case when upper(A.ACCOUNT) in (''ASSETS'',''LIABILITIES'',''INCOME'',''EXPENSES'') then 
	concat(''<span style="font-weight:bold;"><u>'', a.account, ''</u></span>'')
	when upper(a.atype) = ''GROUP'' then concat(''<span style="font-weight:bold;">'', a.account, ''</span>'')
    when upper(a.atype) = ''GROUP'' then upper(a.account)
else
    initcap(a.ACCOUNT) 
end as sampletree, 
case when a.grplevel = 0 then ''F'' else ''T'' end as editable,  
case when a.atype = ''Group'' then ''<span class="material-icons material-icons-style">folder_open</span>''
else 
	case  
     	 when a.acategory = ''Fixed Asset'' then  ''<span class="material-icons material-icons-style">apartment</span>''
		 when a.acategory = ''Cash Book'' then ''<span class="material-icons material-icons-style">payments</span>''
		 when a.acategory = ''Bank Book'' then ''<span class="material-icons material-icons-style">domain</span>''
		 when a.acategory = ''Receivable A/c'' then ''<span class="material-icons material-icons-style">call_received</span>''	 
		 when a.acategory = ''Payable A/c'' then	''<span class="material-icons material-icons-style">call_made</span>'' 
		 when a.acategory = ''Stock A/c'' then ''<span class="material-icons material-icons-style">inventory</span>''
		 else ''<span class="material-icons material-icons-style">account_balance</span>''
	end 
end	as micons, 
a.controlaccount as subledgerflag
from fn_account_tree( cast( :m_companyid as numeric))  a	
left outer join (
select
		PARANTID,
		SUM (OP) as OP,
		SUM (TRADB) as TRADB,
		SUM (TRACR) as TRACR,
		SUM (OP + TRADB - TRACR) as CL
	from
		(		
		select
			A.PARANTID,
			(b.base_debit - b.base_credit) * case
				when b.alie in (''2'', ''3'') then 1-2
				else 1
			end as op,
			0 as TRADB,
			0 as TRACR
		from
			VW_ACCOUNTTREELINK A,
			mv_accountmonthlysummary B
		where
			A.CHILDID = B.mg_accountid
			and B.financial_year = :m_finyr
			and (b.base_debit - b.base_credit) <> 0
			and b.company = cast( :m_companyid as numeric) 	
	union all
	select A.PARANTID,
			0 as OP,
			b.base_debit  as TRADB,
			b.base_credit  as TRACR
		from
			VW_ACCOUNTTREELINK A,
			mv_accountmonthlysummary B
		where		
			A.CHILDID = B.mg_accountid
			and B.financial_year = :m_finyr
			and b.company = cast( :m_companyid as numeric) 
				) a
	group by
		PARANTID
		) B on	
A.mg_accountid  = B.PARANTID 
order by aprefix, sno
