ELSE TO_CHAR(Abs(sum(a.total_sales_amount)), ''FM999,999,999,999'') end,''NIL'') as value, ''iitmsals()'' as link,1 as ord
from invoiceheader  a
WHERE a.company = cast( :m_companyid as numeric)
and a.docdate between cast( :m_fystartdate as date) AND cast( :m_fyenddate as date)
union
select ''Pending Sales Order'' as name,COALESCE ( cast(COUNT(1) as varchar), ''NIL'') as value ,''iivsor()'' as link ,3 as ord
from salesorder_header a ,salesorder_items b 
where a.cancel = ''F''
and a.app_desc = 1 
and b.salesorder_headerid = a.salesorder_headerid
and a.company = cast( :m_companyid as numeric)
AND a.docdate BETWEEN :m_fystartdate AND :m_fyenddate
and (b.order_qty - b.invoiced_qty) > 0
union
SELECT ''Sales Returns'' as name,COALESCE ( case WHEN sum(a.total_sales_amount) > 1000000 THEN round(sum(a.total_sales_amount) / 1000000,2) || '' M'' 
WHEN sum(a.total_sales_amount) < 1000000 and sum(a.total_sales_amount) > 0 THEN TO_CHAR(sum(a.total_sales_amount), ''FM999,999,999,999'')
WHEN SUM(a.total_sales_amount) <= -1000000 THEN  ROUND(SUM(a.total_sales_amount) / 1000000, 2) || '' M''
ELSE TO_CHAR(abs(sum(a.total_sales_amount)), ''FM999,999,999,999'') end, ''NIL'') AS value, ''isalrtrp()'' as link, 2 as ord
FROM salesreturns_header a 
WHERE a.cancel = ''F''
AND a.app_desc = 1
AND a.company = CAST( :m_companyid AS numeric)
AND a.branch = CAST( :m_branchid AS numeric)
AND a.docdate BETWEEN :m_fystartdate AND :m_fyenddate)a
order by ord', 'm_companyid,m_fystartdate,m_fyenddate,m_branchid', 'm_companyid~Numeric~,m_fystartdate~Date/Time~,m_fyenddate~Date/Time~,m_branchid~Numeric~', 'ALL', NULL, 'name,value,link', 'F', '6 Hr', NULL, NULL, NULL, 'T', 'F'),
