('1327770000000', 'F', '0', NULL, 'admin', '2026-06-23 07:00:54', 'admin', '2026-06-12 15:34:14', NULL, '1', '1', NULL, NULL, NULL, 'Customer wise Profitability', NULL, 'For users', '3', 'select party_name,a.itemdesc,a.itemcode,a.categoryname,a.productcategory,a.brand_name,sum(sell_value) sell_value,round(sum(cost_value),2) cost_value,
round(sum(sell_value) -sum(cost_value),2) profit,round(((sum(sell_value) -sum(cost_value))/sum(sell_value))*100,2) profit_margin,
round(sum(cost_value) /sum(sell_value),2) costtosale_ratio,concat(to_char(a.docdate,''Mon''),''-'',to_char(a.docdate,''YY'')) mnth,to_char(a.docdate,''YYYY'') yr,
concat(''Q'',EXTRACT(QUARTER FROM  a.docdate),''-'',to_char(a.docdate,''YY'')) qtr
from (
select a1.docdate,mc.party_name, i.itemdesc,i.itemcode,ic.categoryname,isb.productcategory,br.brand_name,a2.net_amount-coalesce (sr.net_amount,0) sell_value,
(case when coalesce(abs(st.calculated_stockvalue),0) = 0 then coalesce(abs(st.amount),0) else coalesce(abs(st.calculated_stockvalue),0) end/st.qty)*
a2.invoice_qty-coalesce (sr.salesreturn_qty,0) cost_value
from 
invoiceheader a1 join mg_customer mc on a1.customer = mc.mg_customerid
join invoiceitems a2 on a1.invoiceheaderid  = a2.invoiceheaderid 
join item i on a2.itemname  = i.itemid 
join itemcategory ic on i.itemcategory  = ic.itemcategoryid
join productcategory isb on i.productcategory  = isb.productcategoryid 
join brand_master br on i.itembrand  = br.brand_masterid 
join stockvalue st on (a2.deliverynote = st.docid and a2.itemname  = st.itemname )
left outer join (select b.salesinvoice_itemsid,sum(salesreturn_qty) salesreturn_qty,sum(net_amount) net_amount from 
salesreturns_header a
join salesreturns_items b on a.salesreturns_headerid  = b.salesreturns_headerid 
where a.cancel  = ''F''  group by salesinvoice_itemsid) sr on a2.invoiceitemsid  = sr.salesinvoice_itemsid
where a1.cancel  = ''F'') a
group by party_name,a.itemdesc,a.itemcode,a.categoryname,a.productcategory,a.brand_name,concat(to_char(a.docdate,''Mon''),''-'',to_char(a.docdate,''YY'')) ,to_char(a.docdate,''YYYY'') ,
concat(''Q'',EXTRACT(QUARTER FROM  a.docdate),''-'',to_char(a.docdate,''YY''))
order by 1,2', NULL, NULL, 'ALL', NULL, 'party_name,itemdesc,itemcode,categoryname,productcategory,brand_name,sell_value,cost_value,profit,profit_margin,costtosale_ratio,mnth,yr,qtr', 'T', '1 Hr', NULL, 'Customer wise Profitability Data', NULL, 'T', 'F'),
('1186660000000', 'F', '0', NULL, 'ashokk', '2026-06-02 15:31:46', 'ashokk', '2026-06-02 15:31:46', NULL, '1', '1', NULL, NULL, NULL, 'Purchase Summary', NULL, 'For users', '3', 'select a.docdate,s.statejurisdiction state, s.party_name,ic.categoryname,isb.productcategory,br.brand_name,  i.itemdesc,
sum(b.qty) po_qty,sum(grn.grn_qty) recivedqty,sum(returnqty) returnedqty,sum(grn.amount) amount,sum(grn.tax_amount) tax_amount,sum(grn.disc_amount) disc_amount,
sum(grn.bill_value) net_amount,to_char(a.docdate,''Mon'') mnth,to_char(a.docdate,''YYYY'') yr,
